# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KURBAN İBADETİ: TANIMI, HÜKMÜ VE TARİHÎ ARKA PLANI</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Tanımı ve Hükmü</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Sözlük anlamı: Yakınlaşmak</text>\n  <text x="38" y="116" font-size="11" fill="#334155">  (Allah\'a yakınlık sağlamaya vesile).</text>\n  <text x="38" y="140" font-size="11" fill="#334155">• Hükmü: Vacip (veya müekked</text>\n  <text x="38" y="158" font-size="11" fill="#334155">  sünnet) bir malî ibadettir.</text>\n  <text x="38" y="182" font-size="11" fill="#334155">• Delili: &quot;Rabbin için namaz kıl ve</text>\n  <text x="38" y="200" font-size="11" fill="#334155">  kurban kes!&quot; (Kevser suresi, 2)</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Yükümlülük Şartları</text>\n  <text x="258" y="98" font-size="11.5" fill="#334155">1. Müslüman olmak</text>\n  <text x="258" y="122" font-size="11.5" fill="#334155">2. Akıllı ve ergenlik çağına</text>\n  <text x="258" y="140" font-size="11.5" fill="#334155">   (büluğa) ulaşmış olmak</text>\n  <text x="258" y="164" font-size="11.5" fill="#334155">3. Mukim olmak (yolcu olmamak)</text>\n  <text x="258" y="188" font-size="11.5" fill="#334155">4. Nisap miktarı (80,18 g altın)</text>\n  <text x="258" y="206" font-size="11.5" fill="#334155">   mali imkâna sahip olmak</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hz. İbrahim ve Hz. İsmail</text>\n  <text x="478" y="98" font-size="11" fill="#334155">• Hz. İbrahim\'in Allah\'a verdiği</text>\n  <text x="478" y="116" font-size="11" fill="#334155">  söz ve gördüğü sadık rüya.</text>\n  <text x="478" y="140" font-size="11" fill="#334155">• Hz. İsmail\'in tam teslimiyeti</text>\n  <text x="478" y="158" font-size="11" fill="#334155">  ve sabrı (Sâffât, 102-107).</text>\n  <text x="478" y="182" font-size="11" fill="#334155">• Allah\'ın imtihanı kazanan baba</text>\n  <text x="478" y="200" font-size="11" fill="#334155">  ve oğula kurbanlık koç göndermesi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KURBANLIK HAYVANLARIN TÜRLERİ, YAŞ VE HİSSE ŞARTLARI</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Küçükbaş: Koyun ve Keçi</text>\n  <text x="40" y="104" font-size="11.5" fill="#334155">• Yaş Şartı: En az 1 yaşını</text>\n  <text x="40" y="122" font-size="11.5" fill="#334155">  doldurmuş olmalıdır.</text>\n  <text x="40" y="146" font-size="11" fill="#475569">  (Ancak 6 aylık koyun, 1 yaşındaki</text>\n  <text x="40" y="162" font-size="11" fill="#475569">  gibi gösterişliyse kurban olur.)</text>\n  <text x="40" y="190" font-size="11.5" font-weight="bold" fill="#1e40af">• Hisse: Yalnız 1 kişi adına</text>\n  <text x="40" y="208" font-size="11.5" font-weight="bold" fill="#1e40af">  kurban edilebilir.</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Büyükbaş: Sığır ve Manda</text>\n  <text x="262" y="104" font-size="11.5" fill="#334155">• Yaş Şartı: En az 2 yaşını</text>\n  <text x="262" y="122" font-size="11.5" fill="#334155">  tamamlamış olmalıdır.</text>\n  <text x="262" y="150" font-size="11.5" fill="#334155">• Sağlıklı, azaları tam ve</text>\n  <text x="262" y="168" font-size="11.5" fill="#334155">  kusursuz olması gerekir.</text>\n  <text x="262" y="192" font-size="11.5" font-weight="bold" fill="#166534">• Hisse: 1 kişiden 7 kişiye</text>\n  <text x="262" y="210" font-size="11.5" font-weight="bold" fill="#166534">  kadar ortak kesilebilir.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Büyükbaş: Deve ve Kesim Vakti</text>\n  <text x="485" y="104" font-size="11.5" fill="#334155">• Deve Yaşı: En az 5 yaşını</text>\n  <text x="485" y="122" font-size="11.5" fill="#334155">  doldurmuş olmalıdır (1-7 kişi).</text>\n  <text x="485" y="150" font-size="11.5" font-weight="bold" fill="#991b1b">• Kesim Vakti:</text>\n  <text x="485" y="168" font-size="11" fill="#334155">  Bayramın 1. günü bayram namazı</text>\n  <text x="485" y="186" font-size="11" fill="#334155">  sonrası başlar, 3. günü akşam</text>\n  <text x="485" y="204" font-size="11" fill="#334155">  ezanına (güneş batımına) sürer.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KURBAN ETİNİN PAYLAŞIMI VE DİĞER KURBAN ÇEŞİTLERİ</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kurban Etinin Üçe Bölünmesi (Sünnet)</text>\n  <text x="44" y="102" font-size="11.5" fill="#334155">• 1/3 Pay: Kurban kesen kişinin kendi ailesi</text>\n  <text x="44" y="120" font-size="11" fill="#475569">  ve ev halkı için ayrılır.</text>\n  <text x="44" y="148" font-size="11.5" fill="#334155">• 1/3 Pay: Komşulara, akrabalara ve</text>\n  <text x="44" y="166" font-size="11" fill="#475569">  dostlara ikram edilir.</text>\n  <text x="44" y="194" font-size="11.5" fill="#334155">• 1/3 Pay: Kurban kesemeyen yoksul ve</text>\n  <text x="44" y="212" font-size="11" fill="#475569">  ihtiyaç sahibi kimselere dağıtılır.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Adak, Akika ve Şükür Kurbanları</text>\n  <text x="378" y="100" font-size="11.5" font-weight="bold" fill="#92400e">• Adak (Nezir) Kurbanı (Vacip):</text>\n  <text x="378" y="118" font-size="11" fill="#334155">  Dilek gerçekleşince kesilir; adayan ve ailesi</text>\n  <text x="378" y="134" font-size="11" fill="#334155">  etinden YİYEMEZ, tamamı yoksullara dağıtılır.</text>\n  <text x="378" y="162" font-size="11.5" font-weight="bold" fill="#92400e">• Akika Kurbanı (Sünnet):</text>\n  <text x="378" y="180" font-size="11" fill="#334155">  Yeni doğan çocuk için Allah\'a şükür amacıyla</text>\n  <text x="378" y="196" font-size="11" fill="#334155">  kesilir; sahibi ve ailesi etinden yiyebilir.</text>\n  <text x="378" y="220" font-size="11.5" font-weight="bold" fill="#92400e">• Şükür Kurbanı: Nimetlere şükür için kesilir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
